import json
with open('/root/DATA/metadata/employee.json', 'r') as f:
    employees = json.load(f)
print(type(employees))
if isinstance(employees, list):
    print(f'Number of employees: {len(employees)}')
    if len(employees) > 0:
        print('First employee:', json.dumps(employees[0], indent=2))
elif isinstance(employees, dict):
    print(f'Number of keys: {len(employees)}')
    for i, (k, v) in enumerate(employees.items()):
        if i < 3:
            print(f'{k}: {json.dumps(v, indent=2)}')
